from pathlib import Path
from PIL import Image
import io,json,base64,hashlib
V=Path(__file__).resolve().parents[1];root=V.parent.parent
names={'furina':'芙宁娜','zhongli':'钟离','mavuika':'玛薇卡','venti':'温迪','kamisatoayaka':'神里绫华','tartaglia':'达达利亚','aratakiitto':'荒泷一斗','yaemiko':'八重神子','arlecchino':'阿蕾奇诺','wanderer':'流浪者','neuvillette':'那维莱特','clorinde':'克洛琳德','navia':'娜维娅','skirk':'丝柯克'}
def b64(p,resize=None):
 im=Image.open(p).convert('RGBA')
 if resize:im.thumbnail(resize,Image.Resampling.LANCZOS)
 f=io.BytesIO();im.save(f,format='PNG');return 'data:image/png;base64,'+base64.b64encode(f.getvalue()).decode()
chars={}
for key,name in names.items():
 char={'name':name,'groups':{},'research':(V/f'design/cards/{key}-research.md').read_text()}
 for kind in ['idle','walk']:
  d=V/'evidence'/f'{key}-{kind}-review';r=json.load(open(d/'fit.json'));frames=[]
  for i in range(len(r['frames'])):frames.append([b64(d/f'source-cell-{i}.png',(300,300)),b64(d/f'initial-{i}.png'),b64(d/f'optimized-{i}.png')])
  char['groups'][kind]={'frames':frames,'counts':r['rect_counts'],'height':r['optimized_height'],'paletteHash':r['palette_sha256'],'palette':r['palette'],'feet':r['silhouette_bottom_y'],'issues':'固定原格锚点，真实脚底与握点待标定；GIF/拟合证据已生成，不等于动作或真机验收。'+('本组旧步态仍含眼镜，需按无眼镜母版纠正。' if key=='mavuika' and kind=='walk' else '')}
 chars[key]=char
baseline=json.load(open(V/'evidence/v3-accepted-sd.json'));payload={'characters':chars,'baseline':baseline}
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V4 角色研究与拟合预览</title><style>*{box-sizing:border-box}body{margin:0;background:#171b24;color:#e9ecf5;font:15px system-ui}main{max-width:1180px;margin:auto;padding:24px}h1{font-size:26px}p{line-height:1.7;color:#b9c2d4}section{background:#222936;padding:18px;border-radius:14px;margin:16px 0}label{margin-right:12px}select,button,input{padding:8px;background:#313e52;color:white;border:1px solid #53637a;border-radius:6px;margin:4px}button{cursor:pointer}canvas{background:#252936;width:100%;image-rendering:pixelated;display:block}.columns{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.columns h3{font-size:16px}.warn{color:#ffd387}pre{white-space:pre-wrap;line-height:1.75;font-family:inherit}#v3{max-width:640px}#metrics{font-variant-numeric:tabular-nums}input[type=range]{width:260px}@media(max-width:700px){.columns{grid-template-columns:1fr}}</style><main><h1>V4 角色研究与拟合预览</h1><p>14人研究候选 · 已恢复素材复核。显示原格与拟合，不计算伤害，不是正式可玩阵容。所有图已内嵌，可离线打开。</p><section><label>角色 <select id="character"></select></label><label>动作 <select id="group"><option value="idle">待机双姿</option><option value="walk">前走六相</option></select></label><label>背景 <select id="background"><option value="dark">深色</option><option value="light">浅色</option></select></label><button id="play">暂停</button><button id="prev">上一帧</button><button id="next">下一帧</button><button id="restart">重播</button><label><input id="floor" type="checkbox" checked>脚底线与固定锚点</label><input id="scrub" type="range" min="0" max="1" value="0"><div id="metrics"></div><p id="issues" class="warn"></p><div class="columns"><div><h3>源图格（预览缩图）</h3><canvas id="source" width="360" height="360"></canvas></div><div><h3>初始拟合 · 24色+轮廓</h3><canvas id="initial" width="360" height="360"></canvas></div><div><h3>优化拟合 · 18色+轮廓</h3><canvas id="optimized" width="360" height="360"></canvas></div></div><p>三栏使用同一格子显示高度；不按人物轮廓裁切居中。调色板为同角色待机+前走8帧共享；后续扩招还须统一校准。图元上限目标达成不等于脸、比例、步态或性能验收。</p></section><section><h2>V3正式E数据参照</h2><label>角色 <select id="v3char"><option value="raidenshogun">雷电将军</option><option value="nahida">纳西妲</option></select></label><label>层 <select id="layer"><option value="body">身体</option><option value="effect">独立特效</option></select></label><select id="v3pose"></select><canvas id="v3" width="640" height="320"></canvas><p id="v3note"></p><p>直接读取正式E加载器导出的图元数据。旧动作预览中的草神浮空移动不作为当前基线。此栏只重建图元，并非客户端缓冲、判定、GPU或真机测试。</p></section><section><h2>所选角色研究</h2><pre id="research"></pre></section></main><script>const DATA=__DATA__;</script><script>
'use strict';const $=id=>document.getElementById(id);const keys=Object.keys(DATA.characters);let playing=true,frame=0,lastAdvance=0,assets={};
for(const k of keys){const o=document.createElement('option');o.value=k;o.textContent=DATA.characters[k].name;$('character').appendChild(o);}
const current=()=>DATA.characters[$('character').value];const group=()=>current().groups[$('group').value];
async function loadGroup(){const g=group();assets={};await Promise.all(g.frames.flat().map(src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{assets[src]=im;resolve()};im.onerror=reject;im.src=src})));frame=0;$('scrub').max=g.frames.length-1;$('research').textContent=current().research;$('issues').textContent=g.issues;draw();}
function draw(){const g=group();frame=(frame+g.frames.length)%g.frames.length;$('scrub').value=frame;const bg=$('background').value==='light'?'#dfdbcd':'#252936';['source','initial','optimized'].forEach((id,i)=>{const c=$(id).getContext('2d');c.clearRect(0,0,360,360);c.fillStyle=bg;c.fillRect(0,0,360,360);const im=assets[g.frames[frame][i]];if(im){const s=300/im.height;c.imageSmoothingEnabled=i===0;c.drawImage(im,180-im.width*s/2,30,im.width*s,300);}if($('floor').checked){c.strokeStyle='#e7a85a';c.lineWidth=1;c.beginPath();c.moveTo(0,330);c.lineTo(360,330);c.moveTo(180,318);c.lineTo(180,342);c.stroke();}});$('metrics').textContent=`${current().name} · ${frame+1}/${g.frames.length}帧 · 本帧${g.counts[frame]}图元 · 平均${(g.counts.reduce((a,b)=>a+b,0)/g.counts.length).toFixed(1)} · 最大${Math.max(...g.counts)} · 拟合高度${g.height}px · palette ${g.paletteHash.slice(0,12)}`;}
function setupV3(){const key=$('v3char').value;const bank=$('layer').value==='body'?DATA.baseline[key]:DATA.baseline.effects[key==='raidenshogun'?'raiden':'nahida'];$('v3pose').replaceChildren();Object.keys(bank).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=$('layer').value==='body'?k:'特效 '+k;$('v3pose').appendChild(o)});drawV3();}
function drawV3(){const key=$('v3char').value;const body=$('layer').value==='body';const bank=body?DATA.baseline[key]:DATA.baseline.effects[key==='raidenshogun'?'raiden':'nahida'];const p=bank[$('v3pose').value];if(!p)return;const c=$('v3').getContext('2d');c.clearRect(0,0,640,320);c.fillStyle='#252936';c.fillRect(0,0,640,320);const s=body?.7:2;const ax=p.ax||p.w/2,ay=p.ay||p.h;for(let n=0;n<p.n;n++){const o=n*5,[x,y,w,h,ci]=p.bytes.slice(o,o+5);const col=p.pal[ci];c.fillStyle=`rgba(${col[0]},${col[1]},${col[2]},${(col[3]??255)/255})`;c.fillRect(320+(x-ax+(p.ox||0))*s,290+(y-ay)*s,w*s,h*s);}$('v3note').textContent=`${body?'正式身体图元':'正式独立特效'} · ${p.n}图元 · 仅CPU/Canvas可视重建，未验证真实客户端。`;}
$('character').onchange=loadGroup;$('group').onchange=loadGroup;$('background').onchange=draw;$('floor').onchange=draw;$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'暂停':'播放'};$('prev').onclick=()=>{frame--;draw()};$('next').onclick=()=>{frame++;draw()};$('restart').onclick=()=>{frame=0;draw()};$('scrub').oninput=()=>{frame=+$('scrub').value;draw()};$('v3char').onchange=setupV3;$('layer').onchange=setupV3;$('v3pose').onchange=drawV3;
function tick(t){if(playing&&t-lastAdvance>($('group').value==='idle'?350:120)){frame++;draw();lastAdvance=t}requestAnimationFrame(tick)}
window.V4_REVIEW={keys,loadGroup,draw,setupV3,drawV3,get state(){return {character:$('character').value,group:$('group').value,frame,playing}}};loadGroup().then(()=>{setupV3();window.V4_REVIEW.ready=true;requestAnimationFrame(tick)}).catch(e=>{$('issues').textContent='加载错误：'+e.message});
</script></html>'''.replace('__DATA__',json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\/'))
out=root/'V4_Character_Research_Preview.html';out.write_text(html);print(out, out.stat().st_size)
